import React, { useState } from "react";
import {
  TextField,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Typography,
  Container,
  AppBar,
  Toolbar,
  Box,
  IconButton,
} from "@mui/material";
import { Edit, Article, Close as CloseIcon } from "@mui/icons-material";
import axios from "axios";
import { motion, MotionConfig } from "framer-motion";
import useMediaQuery from "@mui/material/useMediaQuery";
import {
  PieChart,
  Pie,
  Cell,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
} from "recharts";

import { generatePDF } from "./download";


// Polyfill for process (important fix for frontend compatibility)
import process from "process";
window.process = process;

function App() {
  const [prompt, setPrompt] = useState("");
  const [essay, setEssay] = useState("");
  const [grade, setGrade] = useState(null);
  const [analysis, setAnalysis] = useState(null);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [loading, setLoading] = useState(false);

  const isMobile = useMediaQuery("(max-width:600px)");
  document.body.style.backgroundColor = "#01225a";

  const handleSubmit = async () => {
    if (!prompt.trim() || !essay.trim()) {
      alert("Please enter both the essay and the prompt.");
      return;
    }

    try {
      setLoading(true);
      const apiUrl = process.env.REACT_APP_API_URL || "http://localhost:5000";
      const response = await axios.post(`${apiUrl}/grade`, {
        prompt,
        essay,
      });
      setGrade(response.data.score);
      setAnalysis(response.data.analysis);
      setDialogOpen(true);
    } catch (error) {
      console.error("Error grading essay:", error);
      alert("Failed to grade essay. Please check your API server.");
    } finally {
      setLoading(false);
    }
  };

  const COLORS = ["#4caf50", "#f44336"];

  const pieChartData = [
    { name: "Scored", value: grade || 0 },
    { name: "Remaining", value: 5 - (grade || 0) },
  ];

  const barChartData = [
    { name: "Obtained", value: grade || 0 },
    { name: "Total", value: 5 },
  ];

  const handleDownload = () => {
    generatePDF({ prompt, essay, grade, analysis });
  };
  
  
  return (
    <>
      <AppBar position="static" sx={{ backgroundColor: "#001434" }}>
        <Toolbar sx={{ justifyContent: "center" }}>
          <Typography variant="h4" sx={{ fontWeight: "bold", textAlign: "center" }}>
            Automatic Essay Grader
          </Typography>
          </Toolbar>
      </AppBar>

      <Container maxWidth="md" sx={{ backgroundColor: "#01225a", marginBottom: "5vw", marginTop: "2vw" }}>
        <MotionConfig transition={{ duration: 0.6, ease: "easeInOut" }}>
          {/* Prompt Field */}
          <motion.div initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }}>
            <Box textAlign="center" mb={4}>
              <Edit fontSize="large" sx={{ color: "#9575cd" }} />
              <Typography variant="h5" mt={2} fontWeight="medium" color="#9575cd">
                Enter Essay Prompt
              </Typography>
            </Box>
            <TextField
              fullWidth
              label="Essay Prompt"
              variant="outlined"
              multiline
              rows={isMobile ? 3 : 4}
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              sx={{
                mb: 4,
                input: { color: "white" },
                textarea: { color: "white" },
                "& .MuiOutlinedInput-root": {
                  "& fieldset": { borderColor: "#757575" },
                  "&:hover fieldset": { borderColor: "#fff" },
                  "&.Mui-focused fieldset": { borderColor: "#9575cd" },
                },
                "& .MuiInputLabel-root": { color: "#aaa" },
                backgroundColor: "#001434",
                borderRadius: 2,
              }}
            />
          </motion.div>

          {/* Essay Field */}
          <motion.div initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}>
            <Box textAlign="center" mb={4}>
              <Article fontSize="large" sx={{ color: "#9575cd" }} />
              <Typography variant="h5" mt={2} fontWeight="medium" color="#9575cd">
                Write Your Essay
              </Typography>
            </Box>
            <TextField
              fullWidth
              label="Your Essay"
              variant="outlined"
              multiline
              rows={isMobile ? 6 : 10}
              value={essay}
              onChange={(e) => setEssay(e.target.value)}
              sx={{
                mb: 4,
                input: { color: "white" },
                textarea: { color: "white" },
                "& .MuiOutlinedInput-root": {
                  "& fieldset": { borderColor: "#757575" },
                  "&:hover fieldset": { borderColor: "#fff" },
                  "&.Mui-focused fieldset": { borderColor: "#9575cd" },
                },
                "& .MuiInputLabel-root": { color: "#aaa" },
                backgroundColor: "#001434",
                borderRadius: 2,
              }}
            />
          </motion.div>

          {/* Submit Button */}
          <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ delay: 0.5 }}>
            <Box display="flex" justifyContent="center">
              <Button
                variant="contained"
                size="large"
                onClick={handleSubmit}
                disabled={loading}
                sx={{
                  backgroundColor: "#7e57c2",
                  color: "#fff",
                  "&:hover": { backgroundColor: "#6a1b9a" },
                  px: 5,
                  py: 1.5,
                  borderRadius: 4,
                }}
              >
                {loading ? "Grading..." : "Submit Essay"}
              </Button>
            </Box>
          </motion.div>
        </MotionConfig>
      </Container>

      {/* Dialog: Results */}
     <Dialog
        open={dialogOpen}
        onClose={() => setDialogOpen(false)}
        maxWidth="sm"
        fullWidth
        PaperProps={{
          sx: {
            bgcolor: "#001f4d",
            color: "white",
            borderRadius: 2,
            p: 2,
            position: "relative",
          },
        }}
      >
        <IconButton onClick={() => setDialogOpen(false)} sx={{ position: "absolute", right: 8, top: 8, color: "red" }}>
          <CloseIcon />
        </IconButton>

        <DialogTitle variant="h5" sx={{ color: "#42a5f5", fontWeight: "bold" }}>
          Essay Grading Result
        </DialogTitle>

        <DialogContent>
          <Typography>
            <span style={{ color: "#9575cd" }}>Your essay has been graded! Final Score:</span>{" "}
            <strong>{grade}</strong>
          </Typography>

          {analysis && (
            <>
              <Typography mt={2}>
                <span style={{ color: "#9575cd" }}>Word Count:</span> <strong>{analysis.word_count}</strong><br /><br />
                <span style={{ color: "#9575cd" }}>Sentence Count:</span> <strong>{analysis.sentence_count}</strong><br /><br />
                <span style={{ color: "#9575cd" }}>Grammar Errors:</span> <strong>{analysis.grammar_issues}</strong><br />
                {analysis.grammar_suggestions?.map((issue, i) => (
                  <Typography key={i} variant="body2">• {issue}</Typography>
                ))}
                <br />
                <span style={{ color: "#9575cd" }}>Prompt Matched:</span> <strong>{analysis.contains_prompt ? "Yes" : "No"}</strong>
              </Typography>

              <Box mt={4} className="pie-chart">
                <Typography variant="h6" align="center" gutterBottom>
                  Score Distribution (Pie Chart)
                </Typography>
                <ResponsiveContainer width="100%" height={250}>
                  <PieChart>
                    <Pie data={pieChartData} dataKey="value" nameKey="name" cx="50%" cy="50%" outerRadius={80} label>
                      {pieChartData.map((_, index) => (
                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                      ))}
                    </Pie>
                  </PieChart>
                </ResponsiveContainer>
              </Box>

              <Box mt={6} className="bar-chart">
                <Typography variant="h6" align="center" gutterBottom>
                  Score Details (Bar Chart)
                </Typography>
                <ResponsiveContainer width="100%" height={250}>
                  <BarChart data={barChartData}>
                    <XAxis dataKey="name" />
                    <YAxis domain={[0, 5]} />
                    <Tooltip />
                    <Bar dataKey="value" fill="#4caf50" />
                  </BarChart>
                </ResponsiveContainer>
              </Box>

            </>
          )}
        </DialogContent>

        <DialogActions sx={{ display: "flex", justifyContent: "space-evenly" }}>
          <Button
            variant="contained"
            color="secondary"
            size="large"
            onClick={() => {
              setDialogOpen(false);
              setPrompt("");
              setEssay("");
              setGrade(null);
              setAnalysis(null);
            }}
          >
            Test Again
          </Button>
          <Button variant="contained" color="secondary" size="large" onClick={handleDownload}>
            Download PDF
          </Button>
        </DialogActions>
      </Dialog> 

    </>
  );
}

export default App;
