import { jsPDF } from "jspdf";
import html2canvas from "html2canvas";

export const generatePDF = async ({ prompt, essay, grade, analysis }) => {
  const doc = new jsPDF();
  const now = new Date();
  const formattedDate = now.toLocaleString();

  let y = 20;
  const lineHeight = 7;
  const pageHeight = doc.internal.pageSize.height;
  const marginBottom = 20;

  const checkPageBreak = (lines = 1) => {
    if (y + lines * lineHeight > pageHeight - marginBottom) {
      doc.addPage();
      y = 20;
    }
  };

  doc.setFontSize(16);
  doc.text("Automatic Essay Grader - Score Report", 20, y);
  y += 10;

  doc.setFontSize(10);
  doc.text(`Generated on: ${formattedDate}`, 20, y);
  y += 10;

  doc.setFontSize(12);

  // Prompt
  const splitPrompt = doc.splitTextToSize(`Essay Prompt: ${prompt}`, 170);
  checkPageBreak(splitPrompt.length);
  doc.text(splitPrompt, 20, y);
  y += splitPrompt.length * lineHeight;

  // Essay
  const splitEssay = doc.splitTextToSize(`Essay: ${essay}`, 170);
  checkPageBreak(splitEssay.length);
  doc.text(splitEssay, 20, y);
  y += splitEssay.length * lineHeight;

  // Score details
  const scoreDetails = [
    `Score: ${grade}/5`,
    `Word Count: ${analysis?.word_count || 0}`,
    `Sentence Count: ${analysis?.sentence_count || 0}`,
    `Grammatical Errors: ${analysis?.grammar_issues || 0}`,
    `Prompt Match: ${analysis?.contains_prompt ? "Yes" : "No"}`,
  ];

  scoreDetails.forEach((line) => {
    checkPageBreak(1);
    doc.text(line, 20, y);
    y += lineHeight;
  });

  // Grammar suggestions
  if (analysis?.grammar_suggestions?.length) {
    checkPageBreak(2);
    y += 5;
    doc.setFontSize(10);
    doc.text("Grammar Suggestions:", 20, y);
    y += lineHeight;

    analysis.grammar_suggestions.forEach((suggestion) => {
      const wrapped = doc.splitTextToSize(`• ${suggestion}`, 160);
      checkPageBreak(wrapped.length);
      doc.text(wrapped, 25, y);
      y += wrapped.length * lineHeight;
    });
  }

  // Footer
  y += 10;
  doc.setFontSize(10);
  doc.text("Generated by Automatic Essay Grader Web App", 20, y);
  doc.text("Developed by Kartik Shriwas", 20, y + 10);
  y += 20;

  // Charts
  try {
    const pieCanvas = await html2canvas(document.querySelector(".pie-chart"));
    const pieImg = pieCanvas.toDataURL("image/png");
    checkPageBreak(110 / lineHeight);
    doc.setFontSize(12);
    doc.text("Score Distribution (Pie Chart)", 20, y);
    y += lineHeight;
    doc.addImage(pieImg, "PNG", 20, y, 170, 100);
    y += 110;

    const barCanvas = await html2canvas(document.querySelector(".bar-chart"));
    const barImg = barCanvas.toDataURL("image/png");
    checkPageBreak(110 / lineHeight);
    doc.text("Score Details (Bar Chart)", 20, y);
    y += lineHeight;
    doc.addImage(barImg, "PNG", 20, y, 170, 100);
    y += 110;

    doc.save("Essay_Grading_Result.pdf");
  } catch (err) {
    console.error("Chart export error:", err);
    doc.save("Essay_Grading_Result.pdf");
  }
};
